Math, Number and BigInt — Worked Example:
Every integer helper, and the difference between them on negative values:

```js
const values = [2.7, -2.7, 2.2, -2.2];
for (const n of values) {
  console.log(n, 'round', Math.round(n), 'trunc', Math.trunc(n), 'floor', Math.floor(n), 'ceil', Math.ceil(n));
}
console.log(Math.sign(-3), Math.sign(0), Object.is(Math.sign(-0), -0));
console.log(Math.min(), Math.max(), Math.min(3, 1, 2));
console.log(Math.hypot(3, 4), Math.imul(3, 4), Math.clz32(1));
```

Random integers need rejection sampling if they must be unbiased, and a shuffle needs Fisher-Yates:

```js
const intBelow = (n) => Math.floor(Math.random() * n);

function shuffle(list) {
  const out = [...list];
  for (let i = out.length - 1; i > 0; i--) {
    const j = intBelow(i + 1);
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
console.log(shuffle([1, 2, 3, 4, 5]).length);

// unbiased and cryptographically strong
const cryptoInt = (max) => {
  const limit = Math.floor(0xffffffff / max) * max;
  const buf = new Uint32Array(1);
  let v;
  do { crypto.getRandomValues(buf); v = buf[0]; } while (v >= limit);
  return v % max;
};
console.log(cryptoInt(6) + 1);
```

