Processes, Signals and child_process:
`execFile` with an argument array cannot be injected into; `exec` with a string can:

```js
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const run = promisify(execFile);

const { stdout } = await run('echo', ['hello', ';rm -rf /']);
console.log(stdout.trim());     // the semicolon is just text

// WRONG: exec(`echo ${userInput}`) — the shell interprets the input
```

Exit codes, missing binaries and bounded waiting are three separate concerns:

```js
import { spawn } from 'node:child_process';

function runNode(script, args = [], timeoutMs = 10_000) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [script, ...args], { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.on('data', (c) => { out += c; if (out.length > 1e6) child.kill(); });
    child.stderr.on('data', (c) => { err += c; });
    child.on('error', reject);                       // not found, not executable
    const timer = setTimeout(() => child.kill('SIGKILL'), timeoutMs);
    child.on('close', (code, signal) => {
      clearTimeout(timer);
      code === 0 ? resolve(out) : reject(new Error(`exit ${code ?? signal}: ${err.slice(0, 200)}`));
    });
  });
}
console.log(await runNode('-e', ['console.log(1 + 1)']));
```

Graceful shutdown drains what is in flight, then forces the issue:

```js
let stopping = false;
const close = async (signal) => {
  if (stopping) { console.log('second signal, exiting now'); process.exit(1); }
  stopping = true;
  console.log('draining on', signal);
  server.closeAllConnections?.();
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 5000).unref();
};
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => void close(sig));
```

Worker Threads and Clustering:
A worker runs in its own isolate, so results cross the boundary as cloned messages:

```js
// worker.js
import { parentPort, workerData } from 'node:worker_threads';
const { numbers } = workerData;
const sum = numbers.reduce((a, b) => a + b, 0);
parentPort.postMessage({ sum, received: numbers.length });

// main.js
import { Worker } from 'node:worker_threads';
const run = (file, data) => new Promise((resolve, reject) => {
  const w = new Worker(new URL(file, import.meta.url), { workerData: data });
  w.once('message', resolve);
  w.once('error', reject);
  w.once('exit', (code) => { if (code !== 0) reject(new Error(`worker exit ${code}`)); });
});
console.log(await run('./worker.js', { numbers: [1, 2, 3, 4] }));
```

A pool reuses workers instead of paying startup per task, and restarts a worker that dies:

```js
class Pool {
  #workers = [];
  #queue = [];
  #busy = new Set();
  constructor(size, file) { this.size = size; this.file = file; }

  spawn() {
    const w = new Worker(new URL(this.file, import.meta.url));
    w.on('message', (msg) => {
      this.#busy.delete(w);
      this.#queue.shift()?.resolve(msg);
      this.dispatch();
    });
    w.on('error', (err) => {
      this.#busy.delete(w);
      this.#queue.shift()?.reject(err);
    });
    return w;
  }

  submit(data) {
    return new Promise((resolve, reject) => {
      this.#queue.push({ data, resolve, reject });
      this.dispatch();
    });
  }

  dispatch() {
    while (this.#busy.size < this.size && this.#queue.length) {
      const w = this.spawn();
      this.#busy.add(w);
      w.postMessage(this.#queue[0].data);
    }
  }
}
```

