Streams, Pipelines and Backpressure:
A Transform must not buffer the whole input, and its callback decides when the chunk is available:

```js
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

const upper = new Transform({
  transform(chunk, encoding, done) {
    done(null, String(chunk).toUpperCase());
  },
});

await pipeline(Readable.from(['a\n', 'b\n']), upper, process.stdout);
```

A framer is the one case that genuinely needs a custom transform, because a message can split across chunks:

```js
class LineSplitter extends Transform {
  #tail = '';
  constructor(opts) { super({ ...opts, decodeStrings: false }); }
  _transform(chunk, _enc, done) {
    const parts = (this.#tail + chunk).split('\n');
    this.#tail = parts.pop() ?? '';
    for (const line of parts) if (line) this.push(line);
    done();
  }
  _flush(done) {
    if (this.#tail) this.push(this.#tail);
    done();
  }
}

const split = new LineSplitter();
const lines = [];
split.on('data', (l) => lines.push(l));
for (const piece of ['a\nb', '\nc\n', 'd']) split.write(piece);
split.end();
await new Promise((r) => split.on('end', r));
console.log(lines);       // [ 'a', 'b', 'c', 'd' ]
```

Backpressure is visible as a `false` return from `write`, and the correct response is to wait for `drain`:

```js
async function writeAll(stream, chunks) {
  for (const chunk of chunks) {
    if (!stream.write(chunk)) {
      await new Promise((r) => stream.once('drain', r));
    }
  }
  stream.end();
}

// or just let the pipeline do it
await pipeline(Readable.from(chunks), destination);
```

Async iteration and object mode are the two modern interfaces: `for await (const chunk of readable)` respects backpressure, and in object mode the high water mark counts objects rather than bytes.

HTTP Servers and Clients:
A server that bounds the body, sets content-length and maps errors in one place:

```js
import { createServer } from 'node:http';

const MAX = 64 * 1024;

async function readJson(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX) { const e = new Error('payload too large'); e.status = 413; throw e; }
    chunks.push(chunk);
  }
  if (!chunks.length) return {};
  try { return JSON.parse(Buffer.concat(chunks).toString('utf8')); }
  catch { const e = new Error('invalid JSON'); e.status = 400; throw e; }
}

const server = createServer(async (req, res) => {
  const send = (status, payload) => {
    const body = JSON.stringify(payload);
    res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) });
    res.end(body);
  };
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    if (req.method === 'GET' && url.pathname === '/health') return send(200, { ok: true });
    if (req.method === 'POST' && url.pathname === '/echo') return send(200, { body: await readJson(req) });
    send(404, { error: 'not found' });
  } catch (err) {
    send(err.status ?? 500, { error: err.message });
  }
});
server.headersTimeout = 10_000;
server.requestTimeout = 30_000;
server.listen(0, '0.0.0.0');
```

A client wrapper that checks the status, parses safely and bounds the wait:

```js
async function api(path, { method = 'GET', body, timeout = 8000, retries = 2 } = {}) {
  for (let attempt = 0; ; attempt++) {
    const res = await fetch(`https://example.test${path}`, {
      method,
      headers: body ? { 'content-type': 'application/json' } : {},
      body: body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(timeout),
    });
    if (res.ok) return res.json();
    if (attempt >= retries || res.status < 500) {
      throw new Error(`${res.status} ${res.statusText}`);
    }
    await new Promise((r) => setTimeout(r, 200 * 2 ** attempt));
  }
}
```

Streaming a large response keeps memory flat, and newline-delimited JSON lets you process it line by line:

```js
const res = await fetch('https://example.test/export.ndjson');
const reader = res.body.pipeThrough(new TextDecoderStream()).getReader();
let buffer = '';
while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += value;
  const lines = buffer.split('\n');
  buffer = lines.pop() ?? '';
  for (const line of lines) if (line) handle(JSON.parse(line));
}
```

Diagnostics, Profiling and Debugging Nod:
Structured logs with redaction, and a request id carried through async work:

```js
import { AsyncLocalStorage } from 'node:async_hooks';
import { randomUUID } from 'node:crypto';

const context = new AsyncLocalStorage();
const SECRET = /token|password|authorization|cookie/i;

function redact(value) {
  if (Array.isArray(value)) return value.map(redact);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, SECRET.test(k) ? '[redacted]' : redact(v)]));
  }
  return value;
}

function log(level, msg, fields = {}) {
  const line = { level, time: new Date().toISOString(), msg, requestId: context.getStore()?.id, ...redact(fields) };
  process.stdout.write(`${JSON.stringify(line)}\n`);
}

await context.run({ id: randomUUID() }, async () => {
  log('info', 'request start', { route: '/api/items', password: 'hunter2' });
});
```

The event loop is the resource to watch, and the histogram is how you see it:

```js
import { monitorEventLoopDelay, performance } from 'node:perf_hooks';
const h = monitorEventLoopDelay({ resolution: 20 });
h.enable();

setInterval(() => {
  const p99 = h.percentile(99) / 1e6;
  if (p99 > 50) log('warn', 'event loop delay high', { p99Ms: Math.round(p99) });
}, 5000).unref();

const t = performance.now();
// ... work
log('debug', 'phase done', { ms: Math.round(performance.now() - t) });
```

